import {existsSync} from 'node:fs';
import {join} from 'node:path';
import {expect} from 'chai';
import {
  BUNDLED_GUIDANCE_DIR,
  PLUGIN_GUIDANCE_COLLECTIONS,
  loadBundledGuidanceCatalog,
  type GuidancePage,
} from '@salesforce/b2c-tooling-sdk/guidance';

// The bundle is generated by `pnpm --filter @salesforce/b2c-tooling-sdk run generate:guidance` (run by pretest).
describe('bundled guidance catalog', () => {
  it('ships the bundle inside the SDK package', () => {
    expect(existsSync(join(BUNDLED_GUIDANCE_DIR, 'index.json'))).to.equal(true);
  });

  it('serves every collection, including MCP skills, and caches per option set', () => {
    const catalog = loadBundledGuidanceCatalog();
    expect(catalog).to.equal(loadBundledGuidanceCatalog());
    const ids = (catalog.read({}) as GuidancePage).collections.map((c) => c.id);
    expect(ids).to.include.members([...PLUGIN_GUIDANCE_COLLECTIONS, 'mcp', 'cap-dev']);
    expect(catalog.readResource('skill://mcp/b2c-mcp-scapi/SKILL.md')).to.include('name: b2c-mcp-scapi');
  });

  it('filters to the requested collections', () => {
    const plugins = loadBundledGuidanceCatalog({collections: PLUGIN_GUIDANCE_COLLECTIONS});
    expect(plugins).to.not.equal(loadBundledGuidanceCatalog());
    expect(plugins.has('b2c-cli/b2c-code')).to.equal(true);
    expect(plugins.has('mcp/b2c-mcp-scapi')).to.equal(false);
    expect(() => plugins.readResource('skill://mcp/b2c-mcp-scapi/SKILL.md')).to.throw();
  });
});
